import { randomUUID } from 'node:crypto';
import { CLIENT_TYPES, PLATFORMS } from '@personalitify/shared-contracts';
import mongoose from 'mongoose';

/**
 * One installation of a client application that belongs to a user.
 *
 * `installationId` is generated by the client once and kept for the lifetime of the
 * installation; signing in again from the same installation reuses the device record.
 */
const deviceSchema = new mongoose.Schema(
  {
    _id: { type: String, default: randomUUID },
    userId: { type: String, required: true, immutable: true },
    installationId: { type: String, required: true, immutable: true },
    name: { type: String, required: true, trim: true, maxlength: 80 },
    clientType: { type: String, enum: CLIENT_TYPES, required: true },
    platform: { type: String, enum: PLATFORMS, required: true },
    appId: { type: String, required: true, maxlength: 64 },
    appVersion: { type: String, default: null, maxlength: 32 },
    osVersion: { type: String, default: null, maxlength: 64 },
    // Reserved for native push delivery (see the notifications module).
    pushToken: { type: String, default: null, select: false },
    lastSeenAt: { type: Date, default: Date.now },
    // Highest event sequence number the device has confirmed as applied.
    syncCursor: { type: Number, default: 0 },
    lastSyncAt: { type: Date, default: null },
  },
  { collection: 'devices', timestamps: true, versionKey: false },
);

deviceSchema.index({ userId: 1, installationId: 1 }, { unique: true });

export const Device = mongoose.model('Device', deviceSchema);

export function serializeDevice(device, { currentDeviceId } = {}) {
  return {
    id: String(device._id),
    installationId: device.installationId,
    name: device.name,
    clientType: device.clientType,
    platform: device.platform,
    appId: device.appId,
    appVersion: device.appVersion,
    osVersion: device.osVersion,
    lastSeenAt: device.lastSeenAt.toISOString(),
    syncCursor: device.syncCursor,
    lastSyncAt: device.lastSyncAt ? device.lastSyncAt.toISOString() : null,
    createdAt: device.createdAt.toISOString(),
    current: currentDeviceId !== undefined && String(device._id) === currentDeviceId,
  };
}
